INSERT INTO "Faq" ("id", "page", "question", "answer", "sortOrder", "isPublished", "updatedAt") VALUES
  ('faq_contact_end_to_end', 'CONTACT', 'Do you handle everything end to end, from concept to on-ground execution?', 'Absolutely. From concept creation and design to planning, manpower, and on-ground execution, we manage every detail end to end. Our disciplined team works like your on-site concierge, ensuring a seamless experience so you can relax and focus on what matters most.', 0, true, CURRENT_TIMESTAMP),
  ('faq_contact_multi_city', 'CONTACT', 'Can you run multi-city rollouts at the same time?', 'Yes. We orchestrate multi-city launches, brand expansion, and large-scale activation rollouts simultaneously, delivering consistent brand experiences, seamless coordination, and precision-led execution across every market.', 1, true, CURRENT_TIMESTAMP),
  ('faq_contact_international', 'CONTACT', 'Do you manage international travel, visas and destination logistics?', 'Absolutely. We manage end-to-end international travel, visa coordination, luxury accommodations, transfers, and destination logistics, ensuring every detail is seamlessly orchestrated for a smooth, stress-free experience across borders.', 2, true, CURRENT_TIMESTAMP),
  ('faq_contact_cities', 'CONTACT', 'Which cities do you cover?', 'We have a pan-India execution network spanning 400+ cities, covering all major Tier 1 markets alongside a strong presence across Tier 2 and Tier 3 cities. Wherever your brand needs to be, we bring local expertise, seamless coordination, and consistent execution.', 3, true, CURRENT_TIMESTAMP),
  ('faq_contact_printing', 'CONTACT', 'Do you have your own printing unit?', 'Yes. Our in-house printing capabilities ensure precision, consistency, and quality across all event collaterals and branding materials, with meticulous quality control checks at every stage.', 4, true, CURRENT_TIMESTAMP),
  ('faq_contact_on_the_day', 'CONTACT', 'How do you make sure everything runs smoothly on the day?', 'Through meticulous planning, detailed run sheets, proactive coordination, and real-time on-ground management, we stay ahead of every detail. Our experienced team anticipates challenges, resolves them swiftly, and ensures every moment unfolds seamlessly, just as envisioned.', 5, true, CURRENT_TIMESTAMP);
